// Pull the useful fields out of an ElevenLabs post-call payload and build the Telegram text.
// Anything that is not an inbound transcription event is dropped quietly
// (outbound calls from other agents share the same webhook, so they are filtered out here).
const esc = (s) => String(s ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const out = [];

for (const item of $input.all()) {
  const body = item.json.body ?? item.json;
  if (body.type !== 'post_call_transcription') continue;

  const d = body.data ?? {};
  if ((d.metadata?.phone_call?.direction ?? 'inbound') !== 'inbound') continue;
  const dc = d.analysis?.data_collection_results ?? {};
  const val = (k) => {
    const v = dc[k]?.value;
    return v === undefined || v === null || String(v).trim() === '' ? 'not given' : String(v).trim();
  };

  const caller = val('caller_name');
  const company = val('company');
  const callback = val('callback_number');
  const reason = val('reason');
  const urgency = val('urgency');
  const outcome = val('outcome');
  const secs = d.metadata?.call_duration_secs ?? 0;
  const started = d.metadata?.start_time_unix_secs
    ? new Date(d.metadata.start_time_unix_secs * 1000).toLocaleString('en-GB', { timeZone: 'Europe/London', dateStyle: 'medium', timeStyle: 'short' })
    : 'unknown time';
  const summary = d.analysis?.transcript_summary ?? 'No summary supplied.';

  const headline = outcome === 'message_taken'
    ? 'New voicemail'
    : 'Voicemail (incomplete, worth a callback?)';

  const message = [
    `📞 <b>${esc(headline)}</b>`,
    `<b>From:</b> ${esc(caller)}${company !== 'not given' ? ' (' + esc(company) + ')' : ''}`,
    `<b>Callback:</b> ${esc(callback)}`,
    `<b>About:</b> ${esc(reason)}`,
    `<b>Urgent:</b> ${esc(urgency)} · <b>Length:</b> ${secs}s · ${esc(started)}`,
    '',
    esc(summary),
  ].join('\n');

  out.push({ json: { conversation_id: d.conversation_id ?? 'unknown', outcome, message } });
}

return out;
